" 2>/dev/null; ls /usr/local/bin/ 2>/dev/null | head -20

node -e "
const fs = require('fs');
// Read SQLite file header to confirm it's a valid db
const buf = fs.readFileSync('/workspace/world.db');
console.log('File size:', buf.length);
console.log('Header:', buf.slice(0, 16).toString('ascii'));
"

node -e "
const Database = require('/tmp/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });

// List tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));

// Product columns
const cols = db.prepare('PRAGMA table_info(products)').all();
console.log('Product columns:', cols.map(c => c.name));

// Search for the product
const rows = db.prepare(\"SELECT * FROM products WHERE product_id='PROD-FA0948' OR name LIKE '%M310%'\").all();
console.log('Product rows:', JSON.stringify(rows, null, 2));

// Check variants
const vcols = db.prepare('PRAGMA table_info(rt_variants)').all();
console.log('Variant columns:', vcols.map(c => c.name));

if (rows.length > 0) {
  const variants = db.prepare('SELECT * FROM rt_variants WHERE product_id=?').all(rows[0].product_id);
  console.log('Variants:', JSON.stringify(variants, null, 2));
}
"

node -e "
const Database = require('/tmp/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });

// Get compatible products
const compatIds = ['PROD-B98D14','PROD-2DBA15','PROD-7C0240','PROD-73FAB4'];
const placeholders = compatIds.map(() => '?').join(',');
const compatProducts = db.prepare('SELECT product_id, name, category, brand, price FROM products WHERE product_id IN (' + placeholders + ')').all(...compatIds);
console.log('Compatible products:', JSON.stringify(compatProducts, null, 2));

// Check for any variants (tau2Retail)
const variants = db.prepare('SELECT * FROM rt_variants WHERE product_id=?').all('PROD-FA0948');
console.log('Variants:', JSON.stringify(variants, null, 2));

// Check warranties
const warranties = db.prepare('SELECT * FROM warranties WHERE product_id=?').all('PROD-FA0948');
console.log('Warranties:', JSON.stringify(warranties, null, 2));
"
